def apply_transformation_v2(input_grid):
    """
    Rule: Find all non-background cells.
    - Group them by their main diagonal (c-r = constant)
    - Group them by their anti-diagonal (r+c = constant)
    - Fill ALL cells on each identified diagonal with the corresponding value

    If multiple values claim the same cell, higher value wins.
    """
    h, w = len(input_grid), len(input_grid[0])
    bg = input_grid[0][0]

    # Track which diagonals have which values
    # diag_main_diff[c-r]: set of values claiming that main diagonal
    # diag_anti_sum[r+c]: set of values claiming that anti-diagonal
    main_diagonals = {}
    anti_diagonals = {}

    for r in range(h):
        for c in range(w):
            val = input_grid[r][c]
            if val != bg:
                diff = c - r      # Main diagonal key
                total = r + c     # Anti-diagonal key

                if diff not in main_diagonals:
                    main_diagonals[diff] = []
                main_diagonals[diff].append(val)

                if total not in anti_diagonals:
                    anti_diagonals[total] = []
                anti_diagonals[total].append(val)

    print(f"Main diagonals found: {list(main_diagonals.keys())}")
    print(f"Anti-diagonals found: {list(anti_diagonals.keys())}")

    # Start with background
    output = [[bg] * w for _ in range(h)]

    # Fill main diagonals
    for diff, vals in main_diagonals.items():
        print(f"  Main diagonal c-r={diff}: values {vals}")
        highest = max(vals)
        for r in range(h):
            c = r + diff
            if 0 <= c < w:
                output[r][c] = highest

    # Fill anti-diagonals (overwrites with potentially higher values)
    for total, vals in anti_diagonals.items():
        print(f"  Anti-diagonal r+c={total}: values {vals}")
        highest = max(vals)
        for r in range(h):
            c = total - r
            if 0 <= r < h and 0 <= c < w:
                output[r][c] = highest

    return output

