def compute_direction_toward_closest_special(r, c, current_val, specials):
    """Find the direction that leads toward the closest special cell"""
    directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]  # NW, NE, SW, SE
    min_dist = float('inf')
    best_dir = None

    for dr, dc in directions:
        r_test, c_test = r + dr, c + dc
        for _ in range(min(100, max(h, w))):  # Look ahead reasonably
            if not (0 <= r_test < h and 0 <= c_test < w):
                break
            for sr, sc, sv in specials:
                if r_test == sr and c_test == sc:
                    dist = abs(r_test - r) + abs(c_test - c)
                    if dist < min_dist:
                        min_dist = dist
                        best_dir = (dr, dc)
                        break
            if best_dir:
                break
            r_test += dr
            c_test += dc
        if best_dir:
            break

    return best_dir

