def apply_transformation(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    bg = input_grid[0][0]

    output = [[bg] * w for _ in range(h)]

    # Find all special cells from INPUT (original positions)
    specials_input = []
    for r in range(h):
        for c in range(w):
            val = input_grid[r][c]
            if val != bg:
                specials_input.append((r, c, val))

    # Process even values first - fill entire diagonals
    for sr, sc, val in specials_input:
        if val % 2 == 0:
            for dr, dc in [(1, 1), (-1, -1)]:  # Main diagonal direction
                r, c = sr + dr, sc + dc
                while 0 <= r < h and 0 <= c < w:
                    output[r][c] = val
                    r += dr
                    c += dc

    # Process odd values - extend toward other special cells
    for sr, sc, val in specials_input:
        if val % 2 == 1:
            best_dir = None

            # Check which directions lead to other special cells
            candidates = []
            for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
                r_test, c_test = sr + dr, sc + dc
                found_special = False
                for d in range(min(50, max(h, w))):
                    if not (0 <= r_test < h and 0 <= c_test < w):
                        break
                    for ssr,ssc,ssv in specials_input:
                        if r_test == ssr and c_test == ssc:
                            dist = abs(r_test - sr) + abs(c_test - sc)
                            candidates.append(((dr, dc), dist))
                            found_special = True
                            break
                    if found_special:
                        break
                    r_test += dr
                    c_test += dc

            if candidates:
                # Pick the direction leading to the closest special cell
                candidates.sort(key=lambda x: x[1])
                best_dir = candidates[0][0]

                if best_dir:
                    dr, dc = best_dir
                    r, c = sr + dr, sc + dc
                    while 0 <= r < h and 0 <= c < w:
                        output[r][c] = val
                        r += dr
                        c += dc

                    print(f"  {val} at ({sr},{sc}) extends in direction {best_dir}")
            else:
                print(f"  {val} at ({sr},{sc}): no candidate direction")

    return output

