import json

# Test algorithm on Demo pair 2 to verify it's still correct
demo_in = G['Demo pair 2 input']
h, w = len(demo_in), len(demo_in[0])
bg = demo_in[0][0]

output = [[bg]*w for _ in range(h)]

specials = []
for r in range(h):
    for c in range(w):
        val = demo_in[r][c]
        if val != bg:
            specials.append((r,c,val))

print("Demo special cells:", specials)

# Evens fill diagonals
for sr, sc, val in specials:
    if val % 2 == 0:
        diag_id = sc - sr
        for r in range(h):
            c = diag_id + r
            if 0 <= c < w:
                output[r][c] = val

# Odds mark originals
for sr, sc, val in specials:
    if val % 2 == 1:
        output[sr][sc] = val

from collections import defaultdict
odds_by_anti = defaultdict(list)
for r, c, v in specials:
    if v % 2 == 1:
        odds_by_anti[r+c].append((r,c))

# Fill between multiple odds on same anti-diagonal
for s, cells in odds_by_anti.items():
    if len(cells) >= 2:
        min_r = min(c[0] for c in cells)
        max_r = max(c[0] for c in cells)
        for rr in range(min_r, max_r+1):
            cc = s - rr
            if 0 <= cc < w and output[rr][cc] == bg:
                output[rr][cc] = 1

demo_pred = output
demo_actual = G['Demo pair 2 output']

match = demo_pred == demo_actual
print(f"Demo match: {match}")

if not match:
    print("\nDifferences:")
    for r in range(h):
        for c in range(w):
            if demo_pred[r][c] != demo_actual[r][c]:
                print(f"  ({r},{c}): predicted={demo_pred[r][c]}, actual={demo_actual[r][c]}")

